#define NHR_COUNT (sizeof nhr_entries / sizeof nhr_entries[0])

static const char *
nhr_lookup(const char *s)
{
    size_t i;
    const char *mode = getenv("NETHACK_RU");
    if (!s || (mode && !strcmp(mode, "0")))
        return NULL;
    for (i = 0; i < NHR_COUNT; ++i)
        if (!strcmp(s, nhr_entries[i].en))
            return nhr_entries[i].display;
    return NULL;
}

/* Only the validated catalog reaches this decoder. Reject unsupported input,
 * consuming one byte, rather than interpreting it as a console code page.
 * Russian letters are U+0410..U+044F, plus U+0401 and U+0451. */
static unsigned
nhr_next(const char **cursor)
{
    const unsigned char *s = (const unsigned char *) *cursor;
    unsigned cp;
    if (!s[0])
        return 0;
    *cursor += 1;
    if (s[0] < 0x80)
        return s[0];
    if ((s[0] == 0xd0 || s[0] == 0xd1) && (s[1] & 0xc0) == 0x80) {
        cp = ((unsigned) (s[0] & 0x1f) << 6) | (s[1] & 0x3f);
        if ((cp >= 0x410 && cp <= 0x44f) || cp == 0x401 || cp == 0x451) {
            *cursor += 1;
            return cp;
        }
    }
    return '?';
}

/* Wrap by displayed cells, not bytes. Never create a fixed-size RU+EN buffer.
 * The caller provides an emitter for one codepoint (or newline).
 * Wrapping can replace a separator space by a newline; all non-space content
 * is retained, including the full English suffix. */
static void
nhr_render(const char *text, int columns, int column,
           void (*emit)(unsigned, void *), void *context)
{
    unsigned cp;
    if (columns < 1)
        columns = 1;
    while (*text) {
        cp = nhr_next(&text);
        if (cp == '\n') {
            emit(cp, context);
            column = 0;
            continue;
        }
        if (cp == ' ' && column > 0) {
            const char *next = text;
            int word = 0;
            while (*next && *next != ' ' && *next != '\n') {
                (void) nhr_next(&next);
                ++word;
            }
            if (word && column + 1 + word > columns) {
                emit('\n', context);
                column = 0;
                continue;
            }
        }
        if (column >= columns) {
            emit('\n', context);
            column = 0;
        }
        emit(cp, context);
        ++column;
    }
}
